export const getAutomotiveProducts = (): Product[] => AUTOMOTIVE_PRODUCTS;

export const getFeaturedAutomotiveProducts = (): Product[] => 
  AUTOMOTIVE_PRODUCTS.filter(product => product.featured);

export const getAutomotiveProductsByBadge = (badge: string): Product[] =>
  AUTOMOTIVE_PRODUCTS.filter(product => product.badge === badge);

export const getAutomotiveProductsByPriceRange = (min: number, max: number): Product[] =>
  AUTOMOTIVE_PRODUCTS.filter(product => product.price >= min && product.price <= max);
